import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    private List<List<Integer>> computeGroupThePeople(int groupSize, List<Integer> people) {
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int person : people) {
            groups.computeIfAbsent(groupSize, k -> new ArrayList<>()).add(person);
        }

        List<List<Integer>> result = new ArrayList<>();
        while (!groups.isEmpty()) {
            int size = groups.keySet().iterator().next();
            List<Integer> group = groups.get(size);
            result.add(group);
            groups.remove(size);
        }
        return result;
    }

    public List<List<Integer>> groupThePeople(int[] groupSizes) {
        List<List<Integer>> peopleList = new ArrayList<>();
        for (int i = 0; i < groupSizes.length; i++) {
            peopleList.add(i);
        }

        return computeGroupThePeople(groupSizes[peopleList.get(0)], peopleList.subList(1, peopleList.size()));
    }
}

