import java.util.ArrayList;

public class Solution {
    public List<Boolean> checkIfPrerequisite(int numCourses, int[][] prerequisites, int[][] queries) {
        boolean[][] adj_matrix = new boolean[numCourses][numCourses];

        // Build adjacency matrix
        for (int[] pre : prerequisites) {
            if (!adj_matrix[pre[0]][pre[1]]) { // Ensure unique prerequisite pairs are added only once
                adj_matrix[pre[0]][pre[1]] = true;
            }
        }

        // Floyd-Warshall algorithm to find all pairs of reachable courses
        for (int k = 0; k < numCourses; k++) {
            for (int i = 0; i < numCourses; i++) {
                if (!adj_matrix[i][k]) continue;
                for (int j = 0; j < numCourses; j++) {
                    adj_matrix[i][j] |= adj_matrix[k][j];
                }
            }
        }

        List<Boolean> answer = new ArrayList<>();
        for (int[] query : queries) {
            answer.add(adj_matrix[query[0]][query[1]]);
        }
        return answer;
    }
}
