        int[] maxSum = new int[1];
        helper(root, maxSum);
        return maxSum[0];
    }

    private int[] helper(TreeNode node, int[] maxSum) {
        if (node == null) {
            return new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, 0, 1};
        }
        // Inline the logic from helper(node.left, maxSum)
        boolean leftValid = true;
        int minLeft = Integer.MAX_VALUE;
        int sumLeft = 0;
        if (node.left != null) {
            int[] leftResult = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, 0, 1};
            // Inline the logic from helper(node.left, maxSum)
            for (int i = 2; i < leftResult.length; ++i) {
                sumLeft += leftResult[i];
            }
            minLeft = Math.min(minLeft, node.val);
        } else {
            leftValid = false;
        }

        // Inline the logic from helper(node.right, maxSum)
        boolean rightValid = true;
        int maxRight = Integer.MIN_VALUE;
        int sumRight = 0;
        if (node.right != null) {
            int[] rightResult = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, 0, 1};
            // Inline the logic from helper(node.left, maxSum)
            for (int i = 2; i < rightResult.length; ++i) {
                sumRight += rightResult[i];
            }
            maxRight = Math.max(maxRight, node.val);
        } else {
            rightValid = false;
        }

        if (leftValid && rightValid && node.val > minLeft && node.val < maxRight) {
            int sum = node.val + sumLeft + sumRight;
            maxSum[0] = Math.max(maxSum[0], sum);
            return new int[]{Math.min(node.val, minLeft), Math.max(node.val, maxRight), sum, 1};
        }

        return new int[]{0, 0, 0, 0};
