            int boarding = Math.min(waiting, 4);
            waiting -= boarding;
            profit += boarding * boardingCost - runningCost;

            if (profit > max_profit) {
                max_profit = profit;
                result = rotations + 1;
            }
            rotations++;
        }
        return result;
    }
}

