public class Solution {

    private boolean processQueue(Queue<TreeNode> queue, int level) {
        if (queue.isEmpty()) return true;

        int size = queue.size();
        int prevVal = (level % 2 == 0) ? 0 : 1000001;

        for (int i = 0; i < size; ++i) {
            TreeNode curr = queue.poll();

            if ((level % 2 == 0 && (curr.val % 2 == 0 || curr.val <= prevVal)) ||
                (level % 2 != 0 && (curr.val % 2 != 0 || curr.val >= prevVal))) {
                return false;
            }

            prevVal = curr.val;

            if (curr.left != null) queue.offer(curr.left);
            if (curr.right != null) queue.offer(curr.right);
        }

        level++; // Incremented here
        return processQueue(queue, level); // Recursive call to continue processing the next level
    }

    private boolean checkEvenOdd(TreeNode node, int level) {
        if (node == null) return true;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(node);

        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; ++i) {
                TreeNode curr = queue.poll();

                if ((level % 2 == 0 && (curr.val % 2 == 0 || curr.val <= prevVal)) ||
                    (level % 2 != 0 && (curr.val % 2 != 0 || curr.val >= prevVal))) {
                    return false;
                }

                prevVal = curr.val;

                if (curr.left != null) queue.offer(curr.left);
                if (curr.right != null) queue.offer(curr.right);
            }

            level++; // Incremented here
        }

        return true; // Added this line to ensure the function returns a value
    }

    public boolean isEvenOddTree(TreeNode root) {
        if (root == null) return false;

        int level = 0;
        return checkEvenOdd(root, level);
    }
